mapper.select:
SELECT sum(a.recharge_money) total_recharge FROM (SELECT p.member_id, p.money recharge_money FROM pay_agent_recharge_log p
WHERE DATE_FORMAT(p.create_time, '%Y-%m-%d') = #{req.inclusive_date}
UNION ALL SELECT m.member_id, m.recharge_money FROM member_recharge_log m WHERE m.`type` = 1
and DATE_FORMAT(m.create_time, '%Y-%m-%d') = #{req.inclusive_date}
UNION ALL SELECT u.member_id, u.recharge_money FROM pay_usdt_recharge u
where DATE_FORMAT(u.create_time, '%Y-%m-%d') = #{req.inclusive_date}
UNION ALL select j.member_id, j.money recharge_money from member_pay_jour j where j.status = '1'
and DATE_FORMAT(j.pay_time, '%Y-%m-%d') = #{req.inclusive_date}
) as a left join member_info as mi on mi.id = a.member_id
where mi.inviter_code in (SELECT inviter_code from member_info where inviter_code = #{req.channelCode})
group by mi.inviter_code

select sum(total_account) from member_info


        and DATE_FORMAT(reg_time, '%Y-%m-%d') = #{req.inclusive_date}


        and inviter_code = #{req.channelCode}

select count(id) total_registration from member_info


        and DATE_FORMAT(reg_time, '%Y-%m-%d') = #{req.inclusive_date}


        and inviter_code = #{req.channelCode}
